SourceCode.Declaration:
/// <summary>
/// Per-company capability checkboxes (the BC "Company Code Mappings" idea): Lifecycle actions
/// shows/hides the lifecycle buttons, Self-billing shows/hides the e-invoice generation buttons.
/// Global (not per-company saved) so an admin maintains every company in one grid; a company
/// without a row - or with a box unchecked - has that capability hidden. The country and
/// capability gates in the services stay as the hard stop behind the buttons.
/// </summary>
public class CELTCompanyCapability extends common
{
}

Method.Source:
/// <summary>
/// The capability row of a company.
/// </summary>
/// <param name = "_company">company id</param>
/// <returns>the row; an empty buffer when the company has none</returns>
public static CELTCompanyCapability find(DataAreaId _company)
{
    CELTCompanyCapability capability;

    select firstonly capability
        where capability.CompanyId == _company;

    return capability;
}

/// <summary>
/// Whether a company already has a capability row.
/// </summary>
/// <param name = "_company">company id</param>
/// <returns>true when present</returns>
public static boolean exist(DataAreaId _company)
{
    return (select firstonly RecId from CELTCompanyCapability
        where CELTCompanyCapability.CompanyId == _company).RecId != 0;
}

/// <summary>
/// Whether the CURRENT company has the Lifecycle actions capability checked - drives the
/// visibility of every lifecycle button (actions, payment history, action log).
/// </summary>
/// <returns>true when checked; false when unchecked or the company has no row</returns>
public static boolean lifecycleActionsEnabled()
{
    return CELTCompanyCapability::find(curExt()).LifecycleActions == NoYes::Yes;
}

/// <summary>
/// Whether the CURRENT company has the Self-billing capability checked - drives the
/// visibility of the Generate e-invoice buttons.
/// </summary>
/// <returns>true when checked; false when unchecked or the company has no row</returns>
public static boolean selfBillingEnabled()
{
    return CELTCompanyCapability::find(curExt()).SelfBilling == NoYes::Yes;
}
